using System.Text.RegularExpressions;
using SqlSchemaDiff.Models;

namespace SqlSchemaDiff.Services;

/// <summary>
/// Reads a script generated by SSMS ("Generate Scripts") and extracts tables,
/// columns, views and foreign keys.
/// </summary>
public class SqlSchemaParser
{
    private const RegexOptions IgnoreCase = RegexOptions.IgnoreCase;

    private static readonly Regex GoSeparator =
        new(@"^[ \t]*GO[ \t]*\r?$", RegexOptions.Multiline | IgnoreCase);

    // Comments and blank lines in front of the real statement.
    private static readonly Regex LeadingNoise =
        new(@"\A(?:\s+|/\*.*?\*/|--[^\r\n]*)*", RegexOptions.Singleline);

    private static readonly Regex DatabaseNamePattern =
        new(@"CREATE\s+DATABASE\s+\[(?<name>[^\]]+)\]", IgnoreCase);

    private static readonly Regex TableHeaderPattern =
        new(@"\ACREATE\s+TABLE\s+\[(?<schema>[^\]]+)\]\.\[(?<name>[^\]]+)\]", IgnoreCase);

    private static readonly Regex ViewHeaderPattern =
        new(@"\ACREATE\s+VIEW\s+\[(?<schema>[^\]]+)\]\.\[(?<name>[^\]]+)\]", IgnoreCase);

    private static readonly Regex ForeignKeyPattern =
        new(@"\AALTER\s+TABLE\s+\[(?<schema>[^\]]+)\]\.\[(?<table>[^\]]+)\]\s+WITH\s+(?:NO)?CHECK\s+ADD\s+CONSTRAINT\s+\[(?<name>[^\]]+)\]\s+FOREIGN\s+KEY",
            IgnoreCase);

    private static readonly Regex ColumnLinePattern =
        new(@"^\[(?<name>[^\]]+)\]\s+(?<definition>.+?)\s*,?$");

    /// <summary>Reads the file (UTF-16 and UTF-8 with BOM are detected automatically) and parses it.</summary>
    public SchemaSnapshot ParseFile(string path) => Parse(File.ReadAllText(path));

    public SchemaSnapshot Parse(string scriptText)
    {
        var snapshot = new SchemaSnapshot { DatabaseName = ExtractDatabaseName(scriptText) };

        foreach (var batch in GoSeparator.Split(scriptText))
        {
            var statement = RemoveLeadingNoise(batch);
            if (statement.Length == 0)
            {
                continue;
            }

            if (TryAddTable(snapshot, statement)) continue;
            if (TryAddView(snapshot, statement)) continue;
            TryAddForeignKey(snapshot, statement);
        }

        return snapshot;
    }

    private static string ExtractDatabaseName(string scriptText)
    {
        var match = DatabaseNamePattern.Match(scriptText);
        return match.Success ? match.Groups["name"].Value : string.Empty;
    }

    private static string RemoveLeadingNoise(string batch)
    {
        var noise = LeadingNoise.Match(batch);
        return batch.Substring(noise.Length).TrimEnd();
    }

    private static bool TryAddTable(SchemaSnapshot snapshot, string statement)
    {
        var match = TableHeaderPattern.Match(statement);
        if (!match.Success)
        {
            return false;
        }

        var table = new TableDefinition
        {
            Schema = match.Groups["schema"].Value,
            Name = match.Groups["name"].Value,
            CreateStatement = statement
        };
        table.Columns.AddRange(ParseColumns(statement));
        snapshot.Tables.Add(table);
        return true;
    }

    private static IEnumerable<ColumnDefinition> ParseColumns(string tableStatement)
    {
        // First line is the CREATE TABLE header; column lines follow until the
        // CONSTRAINT block or the closing parenthesis.
        foreach (var rawLine in tableStatement.Split('\n').Skip(1))
        {
            var line = rawLine.Trim();
            if (line.StartsWith("CONSTRAINT", StringComparison.OrdinalIgnoreCase) || line.StartsWith(')'))
            {
                yield break;
            }

            var match = ColumnLinePattern.Match(line);
            if (match.Success)
            {
                yield return new ColumnDefinition
                {
                    Name = match.Groups["name"].Value,
                    Definition = match.Groups["definition"].Value
                };
            }
        }
    }

    private static bool TryAddView(SchemaSnapshot snapshot, string statement)
    {
        var match = ViewHeaderPattern.Match(statement);
        if (!match.Success)
        {
            return false;
        }

        snapshot.Views.Add(new ViewDefinition
        {
            Schema = match.Groups["schema"].Value,
            Name = match.Groups["name"].Value,
            CreateStatement = statement
        });
        return true;
    }

    private static bool TryAddForeignKey(SchemaSnapshot snapshot, string statement)
    {
        var match = ForeignKeyPattern.Match(statement);
        if (!match.Success)
        {
            return false;
        }

        snapshot.ForeignKeys.Add(new ForeignKeyDefinition
        {
            Name = match.Groups["name"].Value,
            TableFullName = $"[{match.Groups["schema"].Value}].[{match.Groups["table"].Value}]",
            AddStatement = statement
        });
        return true;
    }
}
